<?php declare(strict_types=1); function sR(PDO $db):array{try{return$db->query('SELECT * FROM smarttoolz_settings ORDER BY setting_key ASC')->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){return[];}} $settings=sR($db);$enabled=count(array_filter($settings,fn($x)=>(int)($x['enabled']??0)===1));$json=count(array_filter($settings,fn($x)=>(string)($x['setting_type']??'')==='json')); ?>
<div class="av4-page"><div class="av4-stat-grid"><div class="av4-stat"><b><?=number_format(count($settings))?></b><span>Total settings</span></div><div class="av4-stat green"><b><?=number_format($enabled)?></b><span>Enabled</span></div><div class="av4-stat purple"><b><?=number_format($json)?></b><span>JSON values</span></div><div class="av4-stat blue"><b><?=number_format(count($settings)-$enabled)?></b><span>Disabled</span></div></div>
<div class="av4-card"><div class="av4-head"><div><h2>⚙️ Settings Manager</h2><p>Live application settings with safe typed values.</p></div><span class="av4-chip"><?=number_format(count($settings))?> RECORDS</span></div><form class="av4-form" method="post" action="/smart-toolz/admin/admin-actions.php"><input type="hidden" name="action" value="setting_save"><input type="hidden" name="back" value="settings"><input type="hidden" name="csrf" value="<?=av4h(adminCsrf())?>"><input type="hidden" name="id" value="0"><div><label>Setting key</label><input name="setting_key" placeholder="site.title" required></div><div><label>Type</label><select name="setting_type"><option>text</option><option>number</option><option>boolean</option><option>json</option></select></div><div class="full"><label>Value</label><textarea name="setting_value" placeholder="Value…"></textarea></div><div><label>Description</label><input name="description" placeholder="What this setting controls"></div><div><label>Status</label><select name="enabled"><option value="1">Enabled</option><option value="0">Disabled</option></select></div><div class="full"><button class="av4-btn primary">＋ Save Setting</button></div></form></div>
<div class="av4-card"><div class="av4-head"><div><h2>Configuration inventory</h2><p>Current stored values.</p></div></div><div class="av4-table"><table><thead><tr><th>ID</th><th>Key</th><th>Type</th><th>Value</th><th>Description</th><th>Status</th><th>Updated</th></tr></thead><tbody><?php foreach($settings as $r):?><tr><td><?=av4h($r['id']??'')?></td><td><b><?=av4h($r['setting_key']??'')?></b></td><td><span class="av4-tag purple"><?=av4h($r['setting_type']??'text')?></span></td><td class="mono"><?=av4h(substr((string)($r['setting_value']??''),0,220))?></td><td><?=av4h($r['description']??'')?></td><td><span class="av4-tag <?=!empty($r['enabled'])?'green':'gray'?>"><?=!empty($r['enabled'])?'ON':'OFF'?></span></td><td><?=av4h($r['updated_at']??'')?></td></tr><?php endforeach;if(!$settings):?><tr><td colspan="7" class="empty">No settings stored.</td></tr><?php endif;?></tbody></table></div></div></div>
